import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;

/** Up to 100 URLs; each is validated and created independently. */
public record BulkCreateRequest(@NotEmpty @Size(max = 100) @Valid List<CreateUrlRequest> urls) {
}

public record BulkItem(int index, String status, String code, String shortUrl, String error) {
}

public record BulkCreateResponse(int created, int rejected, List<BulkItem> items) {
}

public record UrlResponse(String code, String shortUrl, String originalUrl, Instant createdAt,

@PostMapping("/bulk")
@Operation(summary = "Create up to 100 short URLs in one request; each item succeeds or is rejected on its own")
public BulkCreateResponse createBulk(@Valid @RequestBody BulkCreateRequest request) {
    List<CreateCommand> commands = request.urls().stream()
            .map(u -> new CreateCommand(u.url(), u.customAlias(), u.expiresAt(), null)).toList();
    List<BatchItemResult> results = service.createBatch(commands);
    List<BulkItem> items = results.stream()
            .map(r -> r.link() != null
                    ? new BulkItem(r.index(), "CREATED", r.link().getShortCode(), baseUrl + "/" + r.link().getShortCode(), null)
                    : new BulkItem(r.index(), "REJECTED", null, null, r.error()))
            .toList();
    int created = (int) items.stream().filter(i -> i.status().equals("CREATED")).count();
    return new BulkCreateResponse(created, items.size() - created, items);
}

